<?php
namespace App\Http\Controllers;
use App\Models\{User,Book,Category,Publisher,Order,BookAccess};
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Storage;
class AdminController extends Controller {
 public function login(){if(auth()->check())return redirect()->route(auth()->user()->isAdmin()?'admin.dashboard':'home');return view('admin.login');}
 public function authenticate(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))return back()->withInput($r->only('email'))->with('error','البريد الإلكتروني أو كلمة المرور غير صحيحة.');if(!$u->isAdmin())return back()->with('error','هذا الحساب ليس لديه صلاحية دخول لوحة الإدارة.');auth()->login($u);$r->session()->regenerate();return redirect()->route('admin.dashboard');}
 public function dashboard(){return view('admin.dashboard',['users'=>User::count(),'books'=>Book::count(),'orders'=>Order::count(),'access'=>BookAccess::count(),'publishers'=>Publisher::count()]);}
 public function users(Request $r){$editing=$r->edit?User::find($r->edit):null;$users=User::when($r->search,fn($q)=>$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('email','like','%'.$r->search.'%')))->latest('id')->get();return view('admin.users',compact('users','editing')); }
 public function userSave(Request $r){$id=(int)$r->id;$rules=['name'=>'required','email'=>'required|email|unique:users,email,'.($id?:'NULL').',id','role'=>'required|in:user,admin'];if(!$id)$rules['password']='required|min:6';else $rules['password']='nullable|min:6';$d=$r->validate($rules);$u=$id?User::findOrFail($id):new User();$u->name=$d['name'];$u->email=$d['email'];$u->role=$d['role'];if(!empty($d['password']))$u->password=Hash::make($d['password']);$u->save();return redirect()->route('admin.users');}
 public function userDelete(Request $r){$u=User::findOrFail($r->id);if($u->role==='admin')return back()->with('error','لا يمكن حذف حساب مدير.');$u->delete();return back();}
 public function books(Request $r){$editing=$r->edit?Book::find($r->edit):null;$books=Book::with('category')->when($r->search,fn($q)=>$q->where(fn($x)=>$x->where('title','like','%'.$r->search.'%')->orWhere('author','like','%'.$r->search.'%')))->latest('id')->get();$categories=Category::orderBy('name')->get();return view('admin.books',compact('books','categories','editing')); }
 public function bookSave(Request $r){$id=(int)$r->id;$d=$r->validate(['title'=>'required','author'=>'required','description'=>'nullable','price'=>'required|numeric|min:0','stock'=>'required|integer|min:0','category_id'=>'required|exists:categories,id','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120']);$b=$id?Book::findOrFail($id):new Book();foreach(['title','author','description','price','stock','category_id'] as $f)$b->$f=$d[$f]??null;if($r->hasFile('image')){if($b->image)Storage::disk('public')->delete($b->image);$b->image=$r->file('image')->store('books','public');}$b->save();return redirect()->route('admin.books');}
 public function bookDelete(Request $r){$b=Book::findOrFail($r->id);if($b->image)Storage::disk('public')->delete($b->image);$b->delete();return back()->with('success','تم حذف الكتاب بنجاح.');}
 public function categories(Request $r){$editing=$r->edit?Category::find($r->edit):null;$categories=Category::when($r->search,fn($q)=>$q->where('name','like','%'.$r->search.'%'))->latest('id')->get();return view('admin.categories',compact('categories','editing'));}
 public function categorySave(Request $r){$id=(int)$r->id;$d=$r->validate(['name'=>'required']);$c=$id?Category::findOrFail($id):new Category();$c->name=$d['name'];$c->save();return redirect()->route('admin.categories');}
 public function categoryDelete(Request $r){$c=Category::findOrFail($r->id);if($c->books()->exists())return back()->with('error','لا يمكن حذف تصنيف يحتوي على كتب. انقل الكتب إلى تصنيف آخر أولًا.');$c->delete();return back()->with('success','تم حذف التصنيف بنجاح.');}
 public function publishers(Request $r){$editing=$r->edit?Publisher::find($r->edit):null;$publishers=Publisher::when($r->search,fn($q)=>$q->where('name','like','%'.$r->search.'%'))->orderBy('name')->get();return view('admin.publishers',compact('publishers','editing'));}
 public function publisherSave(Request $r){$id=(int)$r->id;$d=$r->validate(['name'=>'required|unique:publishers,name,'.($id?:'NULL').',id']);$p=$id?Publisher::findOrFail($id):new Publisher();$p->name=$d['name'];$p->save();return redirect()->route('admin.publishers');}
 public function publisherDelete(Request $r){$p=Publisher::findOrFail($r->id);if($p->books()->exists())return back()->with('error','لا يمكن حذف دار نشر مرتبطة بكتب. غيّر ربط الكتب أولًا.');$p->delete();return back();}
 public function orders(Request $r){$orders=Order::with('items')->latest()->get();return view('admin.orders',compact('orders'));}
 public function orderStatus(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:pending,paid,completed,cancelled']);$order->update(['status'=>$d['status']]);return back();}
 public function access(Request $r){$users=User::where('role','user')->orderBy('name')->get();$books=Book::orderBy('title')->get();$grants=BookAccess::with(['user','book'])->latest('id')->get();return view('admin.access',compact('users','books','grants'));}
 public function grantAccess(Request $r){$d=$r->validate(['user_id'=>'required|exists:users,id','book_id'=>'required|exists:books,id']);BookAccess::firstOrCreate(['user_id'=>$d['user_id'],'book_id'=>$d['book_id']],['granted_by'=>auth()->id()]);return back()->with('success','تم فتح الكتاب للمستخدم.');}
 public function logout(Request $r){auth()->logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('admin.login');}
}